from __future__ import annotations
import base64
import json
import re
from datetime import datetime, timezone
from pathlib import Path

REPO_ROOT = Path.cwd()
GENERATED_AT = datetime.now(timezone.utc).isoformat()

def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace") if path.exists() else ""

def write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")

def write_json(path: Path, payload) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")

def backup(path: Path, label: str) -> None:
    if path.exists():
        dest = REPO_ROOT / "reports" / "benchmarks" / "v0_4_0" / "backups" / f"{path.name}_before_v0_4_0_{label}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.bak"
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(read_text(path), encoding="utf-8")

for rel in ["README.md", "AGENTS.md", "rcc/nexus/task_routing_matrix.md", "rcc/nexus/route_map.json", "rcc/nexus/agent_handoff_contract.md"]:
    backup(REPO_ROOT / rel, rel.replace("/", "_"))

mini_readmes = {
    "configs/seeds/tests/README.md": "# Synthetic Gate Test Seeds\n\nRole: controlled synthetic claim cards for Tau Scaling gate isolation.\n\nThese seeds are local-runtime diagnostics only. They do not validate silicon, product performance, manufacturing capability, process-node equivalence, benchmark superiority, or a universal Tau Scaling law.\n\nPrimary runner:\n\n```powershell\npython scripts/benchmarks/run_synthetic_gate_suite.py\n```\n",
    "reports/gates/README.md": "# Gate Reports\n\nRole: synthetic gate-suite reports and gate-level diagnostics.\n\nBoundary: gate-suite reports validate local classifier behavior only. They are not silicon validation, product validation, manufacturing validation, process-node equivalence, or universal Tau Scaling proof.\n",
    "reports/findings/README.md": "# Finding Reports\n\nRole: finding-level charts and summaries emitted by synthetic gate tests.\n\nBoundary: findings explain local runtime downgrade behavior only. They are not external validation.\n",
    "visuals/benchmarks/README.md": "# Benchmark Visuals\n\nRole: visual benchmark outputs for Tau Scaling runtime diagnostics.\n\nBoundary: charts are local observability artifacts only.\n",
    "visuals/findings/README.md": "# Finding Visuals\n\nRole: per-finding visual charts for synthetic gate-suite diagnostics.\n\nBoundary: finding charts visualize local classifier behavior only.\n",
}
for rel, body in mini_readmes.items():
    write_text(REPO_ROOT / rel, body)

runner_b64 = ""
runner_text = base64.b64decode(runner_b64.encode("ascii")).decode("utf-8")
write_text(REPO_ROOT / "scripts" / "benchmarks" / "run_synthetic_gate_suite.py", runner_text)

readme_path = REPO_ROOT / "README.md"
readme = read_text(readme_path)
readme = re.sub(r"Current checkpoint: \*\*TAU-SCALING-SA v0\.3\.3[^*]*\*\*", "Current checkpoint: **TAU-SCALING-SA v0.4.0 - Synthetic Gate Test Suite + Benchmark Finding Charts**", readme)
readme = re.sub(r"Previous seal: \*\*TAU-SCALING-SA v0\.3\.3[^*]*\*\*", "Previous seal: **TAU-SCALING-SA v0.3.3e - Agent Contract Geometry Sync**", readme)
readme = re.sub(r"\| Current checkpoint \| TAU-SCALING-SA v0\.3\.3[a-z]? \|", "| Current checkpoint | TAU-SCALING-SA v0.4.0 |", readme)
readme = re.sub(r"\| Public README / agent-geometry sync \| v0\.3\.3e \|", "| Synthetic gate suite | v0.4.0 / benchmark + finding charts |", readme)

if "| Synthetic gate report | `reports/gates/latest_synthetic_gate_report.md` |" not in readme:
    readme = readme.replace("| Benchmark harness | 12 runs / 12 unique IDs / 0 duplicates |\n", "| Benchmark harness | 12 runs / 12 unique IDs / 0 duplicates |\n| Synthetic gate report | `reports/gates/latest_synthetic_gate_report.md` |\n| Finding charts | `reports/findings/latest_finding_charts.md` |\n")

